#!/bin/bash
# Generates the illustrative site photos with Gemini (see GEMINI_IMAGE_GENERATION.md).
# Usage: bash gen/generate.sh [name ...]   — no arguments = all images that do not exist yet
OUT="$(cd "$(dirname "$0")" && pwd)"
GEN="/Users/ivan/Downloads/Клод сайти/google-image-gen-api-starter-main копія"
Q="Ultra-realistic professional photography, natural colours, sharp focus, 4K, no text, no lettering, no logos, no watermark"
CTX="in an ordinary German apartment building in Lower Saxony"

names=(); ratios=(); prompts=()
add() { names+=("$1"); ratios+=("$2"); prompts+=("$3"); }

add svc-turnkey 1:1 "Close-up of a craftsman's hand in a dark charcoal work jacket holding out a small ring with two apartment keys, in the softly blurred background a freshly renovated bright living room $CTX: matte white walls, warm oak-look laminate floor, white skirting boards, large window with evening sun. Shallow depth of field, warm golden light from the window on the left. $Q"
add svc-bath 1:1 "Freshly renovated modern bathroom $CTX: walk-in shower with frameless clear glass panel and matte black rain shower, large-format anthracite porcelain floor tiles, white matte wall tiles, wall-hung white WC, floating oak vanity with white washbasin and matte black tap, round backlit mirror, white towel radiator. Nobody present. Soft diffused daylight plus warm mirror light. Eye-level interior photography. $Q"
add svc-electric 1:1 "Close-up of an electrician's hands in thin grey work gloves fitting a white flush-mounted double wall socket into a freshly plastered white wall with an insulated screwdriver, neatly stripped copper wires visible, a red and black two-pole voltage tester lying on a folding ladder step beside. Dark charcoal workwear sleeve. $CTX. Soft daylight from the left, shallow depth of field. $Q"
add svc-paint 1:1 "A painter seen from behind in clean white work trousers and dark charcoal t-shirt rolling smooth matte white paint onto a wall with a wide paint roller on an extension pole, room under renovation $CTX, floor covered with grey protective fleece, masking tape along the white door frame, aluminium ladder and paint bucket at the side. Bright even daylight from a window on the right. $Q"
add svc-floor 1:1 "Low-angle close-up of a floor layer's hands in dark work gloves clicking a warm oak-look laminate plank into place, grey underlay visible on the unfinished part of the floor, rubber mallet, tapping block and yellow spacer wedges next to the white wall, knee pads on dark work trousers. $CTX. Warm daylight from a window, shallow depth of field. $Q"
add svc-tiles 1:1 "Close-up of a tiler's hands in work gloves setting a large-format anthracite porcelain floor tile into fresh grey tile adhesive combed with a notched trowel, orange tile levelling clips and wedges between already laid tiles, spirit level lying on the tiles. Bathroom under renovation $CTX. Soft diffused light, shallow depth of field. $Q"
add svc-plumbing 1:1 "Close-up of a plumber's hands tightening a chrome angle valve under a new white wall-mounted washbasin with an adjustable wrench, chrome trap and flexible braided hoses, light grey tiled wall behind, dark charcoal workwear sleeve, a small tool bag on the anthracite tiled floor. $CTX. Soft diffused light, shallow depth of field. $Q"
add svc-demolition 1:1 "A worker seen from behind in dark charcoal workwear, white hard hat, dust mask and safety glasses removing old beige wall tiles in a bathroom with a demolition hammer drill, broken tiles and rubble on the floor, grey rubble sacks and a bucket at the side, fine dust in a beam of light from a small window, exposed brick wall. $CTX. Dramatic natural side light. $Q"
add svc-rental 1:1 "Empty, spotlessly clean freshly renovated room ready for new tenants $CTX: matte white walls, warm oak-look laminate floor, white panel radiator under a large window with balcony door, on the anthracite window sill in the foreground a ring with two keys and a small green plant in a white pot. Bright morning light, long soft window reflections on the floor. Nobody present. $Q"
add benefits 16:9 "Two craftsmen in dark charcoal workwear standing in a bright room under renovation $CTX, seen from the side and slightly behind, looking together at a floor plan on a tablet; one points at the freshly plastered white wall. New oak-look laminate partly laid, aluminium ladder, neatly stacked boxes of tiles and paint buckets in the background, large window with daylight from the left. Both figures in the upper two thirds of the frame, lower third only floor. Documentary-style photography, natural warm light. $Q"
add review-1 4:3 "Freshly renovated compact kitchen $CTX: matte white handleless cabinets, warm oak worktop, white metro wall tiles with anthracite joints, matte black tap, built-in oven, anthracite floor tiles, small window with white frame, a potted basil on the worktop. Nobody present. Soft daylight plus warm under-cabinet light. Eye-level interior photography. $Q"
add review-2 4:3 "Freshly renovated bright hallway of an apartment $CTX: matte white walls, warm oak-look laminate floor, white interior doors with brushed steel handles, white skirting boards, a matte black ceiling spotlight rail, a slim oak bench and a round mirror, open door at the end showing a sunlit room. Nobody present. Warm natural light. Eye-level interior photography. $Q"
add faq 3:4 "Close-up of a craftsman's hands in a dark charcoal work jacket writing measurements on a clipboard with a pencil, a yellow folding rule and a laser distance meter lying on an anthracite window sill, softly blurred renovated room with white walls and oak-look laminate behind. The paper shows only hand-drawn lines of a room sketch without readable words. $CTX. Warm daylight from the window, shallow depth of field. $Q"
add step-1 1:1 "A homeowner's hands holding a modern smartphone at chest height and typing a message with the thumb, seen from over the shoulder, medium distance so the whole phone and both hands fit comfortably in the centre of the frame. In the softly blurred background a dated room $CTX waiting for renovation: old beige wallpaper, worn carpet, an old radiator under the window. The phone screen is a plain soft glow with no readable text. Light beige sweater sleeves. Natural daylight from the window on the left, shallow depth of field. $Q"
add step-2 1:1 "A craftsman in dark charcoal workwear seen from behind and from the side measuring an empty room $CTX with a handheld laser distance meter pointed at the opposite white wall, a clipboard under his arm, old parquet floor, large window with daylight on the left. Documentary-style photography, natural light. $Q"
add step-3 1:1 "Close-up of two hands: a craftsman's hand in a dark charcoal work jacket handing a ring with two apartment keys to a client's hand in a light beige sweater, in the softly blurred background a spotless freshly renovated living room $CTX with white walls and warm oak-look laminate, golden evening light from the window. Shallow depth of field. $Q"
add turnkey-start 4:5 "Empty room $CTX stripped back for a complete renovation: bare grey cement screed floor, walls stripped to raw plaster with patches of old wallpaper remnants, open cable channels chased into the wall with grey conduits, an old ribbed radiator under a large window with white frame, exposed ceiling lamp wire, grey rubble sacks, a bucket and a demolition hammer in the corner, fine dust in the air. Nobody present. Eye-level wide-angle view into the room corner with the window on the left wall, daylight from the window. Documentary construction photography. $Q"
add hero 16:9 "Interior of a freshly renovated apartment living room $CTX. Smooth matte white walls, warm oak-look laminate floor with clean white skirting boards, a large triple-glazed window with white frame and anthracite window sill, a modern white panel radiator, matte black pendant lamp, one anthracite fabric sofa and a small oak side table, dark charcoal accent wall on the right with warm brass wall light. Early evening, warm golden light coming through the window from the left. Nobody present. Wide-angle architectural interior photography at eye level. $Q"

want=("$@")
cd "$GEN" || exit 1
running=0
for i in "${!names[@]}"; do
  n="${names[$i]}"
  if [ ${#want[@]} -gt 0 ]; then [[ " ${want[*]} " == *" $n "* ]] || continue; else [ -f "$OUT/$n.jpg" ] && continue; fi
  ( uv run python main.py "$OUT/$n.jpg" "${prompts[$i]}" --aspect "${ratios[$i]}" >"$OUT/$n.log" 2>&1 && echo "done $n" || echo "FAILED $n" ) &
  running=$((running + 1))
  if [ $running -ge 4 ]; then wait -n 2>/dev/null || wait; running=$((running - 1)); fi
done
wait
